"""Test suite for pytest python collection module."""
import pytest


def test_pytest_addoption():
    """Test that pytest_addoption adds the correct options."""
    from _pytest.python import pytest_addoption

    class MockParser:
        def __init__(self):
            self.groups = {}
            self.inis = []

        def getgroup(self, name):
            if name not in self.groups:
                self.groups[name] = MockGroup()
            return self.groups[name]

        def addini(self, *args, **kwargs):
            self.inis.append((args, kwargs))

    class MockGroup:
        def __init__(self):
            self.options = []

        def addoption(self, *args, **kwargs):
            self.options.append((args, kwargs))

    parser = MockParser()
    pytest_addoption(parser)

    # Check that options were added
    assert len(parser.groups["general"].options) >= 2
    option_names = [opt[0][0] for opt in parser.groups["general"].options]
    assert "--fixtures" in option_names or "--funcargs" in option_names
    assert "--fixtures-per-test" in option_names


