def test_pytest_generate_tests_alt_spellings():
    """Test that pytest_generate_tests catches misspelled parametrize."""
    from _pytest.python import pytest_generate_tests
    from _pytest.outcomes import fail

    class MockDefinition:
        def __init__(self, marker_name):
            self.marker_name = marker_name
            self._markers = {marker_name: True} if marker_name else {}

        def get_closest_marker(self, name):
            return self._markers.get(name)

        @property
        def function(self):
            class Func:
                __name__ = "test_func"
            return Func()

    class MockMetafunc:
        def __init__(self, marker_name):
            self.definition = MockDefinition(marker_name)

    # Test misspelling detection
    for misspelling in ["parameterize", "parametrise", "parameterise"]:
        metafunc = MockMetafunc(misspelling)
        with pytest.raises(Exception):
            pytest_generate_tests(metafunc)


