def test_call_spec2_copy():
    """Test CallSpec2.copy method."""
    from _pytest.python import CallSpec2

    class MockMetafunc:
        pass

    cs = CallSpec2(MockMetafunc())
    cs.funcargs['arg1'] = 'value1'
    cs.params['arg2'] = 'value2'
    cs.marks.append('mark1')
    cs.indices['arg1'] = 0

    cs_copy = cs.copy()

    assert cs_copy.funcargs == cs.funcargs
    assert cs_copy.params == cs.params
    assert cs_copy.marks == cs.marks
    assert cs_copy.indices == cs.indices


