def test_call_with_optional_argument():
    """Test _call_with_optional_argument function."""
    from _pytest.python import _call_with_optional_argument

    class Counter:
        def __init__(self):
            self.count = 0

        def func_no_arg(self):
            self.count += 1

        def func_one_arg(self, arg):
            self.count += arg

    counter = Counter()

    # Test with no argument
    _call_with_optional_argument(counter.func_no_arg, "any")
    assert counter.count == 1

    # Reset
