class MiddlewareIntegrationTests(SimpleTestCase):
    """Integration tests for middleware decorators."""

    def test_full_middleware_flow(self):
        """Test complete middleware flow with all hooks."""
        from django.utils.decorators import make_middleware_decorator

        call_order = []

        class FullMiddleware:
            def __init__(self, view_func):
                pass

            def process_request(self, request):
                call_order.append('process_request')
                return None

            def process_view(self, request, view_func, args, kwargs):
                call_order.append('process_view')
                return None

            def process_exception(self, request, exception):
                call_order.append('process_exception')
                return None

            def process_response(self, request, response):
                call_order.append('process_response')
                return response

        decorator_factory = make_middleware_decorator(FullMiddleware)
        decorator = decorator_factory()

        def view_func(request):
            call_order.append('view_executed')
            return "response"

        decorated = decorator(view_func)
        response = decorated(None)
        self.assertEqual(response, "response")
        self.assertIn('process_request', call_order)
        self.assertIn('process_view', call_order)
        self.assertIn('view_executed', call_order)
        self.assertIn('process_response', call_order)

    def test_middleware_early_return(self):
        """Test middleware that returns early from process_request."""
        from django.utils.decorators import make_middleware_decorator

        class EarlyReturnMiddleware:
            def __init__(self, view_func):
                pass

            def process_request(self, request):
                return "early"

