from django.forms.boundfield import BoundField, BoundWidget
from django.test import SimpleTestCase


class MockForm:
    """Mock form for testing BoundField."""
    def __init__(self, auto_id=True, is_bound=False, data=None, errors=None):
        self.auto_id = auto_id
        self.is_bound = is_bound
        self._data = data or {}
        self._errors = errors or {}
        self.label_suffix = ':'
        self.use_required_attribute = True
        self.renderer = None

    def add_prefix(self, name):
        return name

    def add_initial_prefix(self, name):
        return 'initial-' + str(name) if name else ''

    def get_initial_for_field(self, field, name):
        return getattr(field, 'initial', None)

    def _widget_data_value(self, widget, html_name):
        return self._data.get(html_name)

    @property
    def errors(self):
        return self._errors


class MockField:
    """Mock field for testing BoundField."""
    def __init__(self, label=None, help_text='', required=True, disabled=False, 
                 localize=False, show_hidden_initial=False, initial=None, label_suffix=None):
        self.label = label
        self.help_text = help_text
        self.required = required
        self.disabled = disabled
        self.localize = localize
        self.show_hidden_initial = show_hidden_initial
        self.initial = initial
        self.label_suffix = label_suffix
        self.widget = MockWidget()

    def bound_data(self, data, initial):
        return data if data is not None else initial

    def prepare_value(self, value):
        return value

    def has_changed(self, initial_value, data):
        return initial_value != data

    def hidden_widget(self):
        return MockWidget(is_hidden=True)

    def use_required_attribute(self, initial):
        return self.required


class MockWidget:
