from django.test import SimpleTestCase
from django.utils.safestring import mark_safe

from ..utils import setup


class JoinTests(SimpleTestCase):
    """Tests for the join filter."""

    @setup({"join01": "{{ a|join:', ' }}"})
    def test_join_basic(self):
        output = self.engine.render_to_string("join01", {"a": ["a", "b", "c"]})
        self.assertEqual(output, "a, b, c")

    @setup({"join02": "{{ a|join:'' }}"})
    def test_join_empty_separator(self):
        output = self.engine.render_to_string("join02", {"a": ["a", "b", "c"]})
        self.assertEqual(output, "abc")

    @setup({"join03": "{{ a|join:' - ' }}"})
    def test_join_custom_separator(self):
        output = self.engine.render_to_string("join03", {"a": ["x", "y", "z"]})
        self.assertEqual(output, "x - y - z")

    @setup({"join04": '{{ a|join:", " }} {{ b|join:", " }}' })
    def test_join_with_html_entities(self):
        output = self.engine.render_to_string(
            "join04", {"a": ["a&b", "x"], "b": [mark_safe("a&b"), "x"]}
        )
        self.assertEqual(output, "a&amp;b, x a&b, x")

    @setup(
        {
            "join05": (
                '{% autoescape off %}{{ a|join:", " }} {{ b|join:", " }}{% endautoescape %}'
            )
        }
    )
    def test_join_autoescape_off(self):
        output = self.engine.render_to_string(
            "join05", {"a": ["a&b", "x"], "b": [mark_safe("a&b"), "x"]}
        )
        self.assertEqual(output, "a&b, x a&b, x")

    @setup({"join06": "{{ empty|join:', ' }}"})
    def test_join_empty_list(self):
        output = self.engine.render_to_string("join06", {"empty": []})
        self.assertEqual(output, "")

    @setup({"join07": '{{ a|join:"\\n" }}'})
    def test_join_newline_separator(self):
        output = self.engine.render_to_string("join07", {"a": ["line1", "line2"]})
        # In templates, \\n is rendered as literal \n
        self.assertEqual(output, "line1\\nline2")

    @setup({"join08": "{{ a|join:'|' }}"})
    def test_join_pipe_separator(self):
        output = self.engine.render_to_string("join08", {"a": ["1", "2", "3"]})
        self.assertEqual(output, "1|2|3")


