        assert transformer._sklearn_output_config['transform'] == 'default'

    def test_multiple_transformers_different_configs(self):
        """Test multiple transformers with different output configs."""
        from sklearn.utils._set_output import _SetOutputMixin

        class Transformer1(_SetOutputMixin, auto_wrap_output_keys=('transform',)):
            def transform(self, X):
                return X

            def get_feature_names_out(self):
                return ['a', 'b']

        class Transformer2(_SetOutputMixin, auto_wrap_output_keys=('transform',)):
            def transform(self, X):
                return X

            def get_feature_names_out(self):
                return ['c', 'd']

        t1 = Transformer1()
        t2 = Transformer2()

        t1.set_output(transform='pandas')
        t2.set_output(transform='default')

        import pandas as pd
        X = np.array([[1, 2], [3, 4]])

        r1 = t1.transform(X)
        r2 = t2.transform(X)

        assert isinstance(r1, pd.DataFrame)
        assert isinstance(r2, np.ndarray)

    def test_set_output_preserves_original_config(self):
        """Test that set_output doesn't modify original config when transform=None."""
        from sklearn.utils._set_output import _SetOutputMixin

        class SimpleTransformer(_SetOutputMixin, auto_wrap_output_keys=('transform',)):
            def transform(self, X):
                return X

            def get_feature_names_out(self):
                return ['a', 'b']

        transformer = SimpleTransformer()
        transformer.set_output(transform='pandas')

        original_config = transformer._sklearn_output_config.copy()
        transformer.set_output(transform=None)

        assert transformer._sklearn_output_config == original_config

