        self.assertIn('autofocus', username_widget.attrs)
        self.assertTrue(username_widget.attrs['autofocus'])

    def test_clean_with_invalid_credentials(self):
        with patch('django.contrib.auth.forms.authenticate') as mock_authenticate:
            mock_authenticate.return_value = None
            form = self.form_class(data={
                "username": "invaliduser",
                "password": "wrongpassword",
            })
            form.is_valid()
            # Django puts validation errors for invalid login in __all__
            self.assertIn("__all__", form.errors.keys())
            self.assertTrue(form.errors["__all__"])

    def test_clean_with_inactive_user(self):
        mock_user = MagicMock()
        mock_user.is_active = False

        with patch('django.contrib.auth.forms.authenticate') as mock_authenticate:
            mock_authenticate.return_value = mock_user
            form = self.form_class(data={
                "username": "inactiveuser",
                "password": "anypassword",
            })
            # When user is inactive, ValidationError is raised during is_valid()
            # which causes is_valid() to return False and add error to __all__
            result = form.is_valid()
            self.assertFalse(result)
            self.assertIn("__all__", form.errors.keys())

    def test_confirm_login_allowed_rejects_inactive(self):
        mock_user = MagicMock()
        mock_user.is_active = False

        form = self.form_class()
        with self.assertRaises(Exception):
            form.confirm_login_allowed(mock_user)

    def test_get_user_returns_user_cache(self):
        mock_user = MagicMock()
        form = self.form_class()
        form.user_cache = mock_user
        self.assertEqual(form.get_user(), mock_user)

    def test_get_invalid_login_error_format(self):
        form = self.form_class()
        error = form.get_invalid_login_error()
        self.assertIsNotNone(error)


