class URLencodeTests(SimpleTestCase):
    def setUp(self):
        from django.utils.http import urlencode
        from django.utils.datastructures import MultiValueDict
        self.urlencode = urlencode
        self.MultiValueDict = MultiValueDict

    def test_urlencode_dict(self):
        result = self.urlencode({'key': 'value'})
        self.assertIn('key=value', result)

    def test_urlencode_none_value_raises_error(self):
        with self.assertRaises(TypeError):
            self.urlencode({'key': None})

    def test_urlencode_multivaluedict(self):
        mvd = self.MultiValueDict({'key': ['value1', 'value2']})
        result = self.urlencode(mvd, doseq=True)
        self.assertIn('key=value1', result)
        self.assertIn('key=value2', result)

    def test_urlencode_doseq_true_list(self):
        result = self.urlencode({'key': ['a', 'b']}, doseq=True)
        self.assertIn('key=a', result)
        self.assertIn('key=b', result)

    def test_urlencode_doseq_false_list(self):
        result = self.urlencode({'key': ['a', 'b']}, doseq=False)
        self.assertIn("key=['a', 'b']", result)

    def test_urlencode_generator_doseq(self):
        def gen():
            yield 'a'
            yield 'b'
        result = self.urlencode({'key': gen()}, doseq=True)
        self.assertIn('key=a', result)
        self.assertIn('key=b', result)

    def test_urlencode_none_in_generator_raises_error(self):
        def gen():
            yield 'a'
            yield None
        with self.assertRaises(TypeError):
            self.urlencode({'key': gen()}, doseq=True)

    def test_urlencode_bytes_value(self):
        result = self.urlencode({'key': b'value'})
        self.assertIn('key=value', result)


