class TruncatorTests(SimpleTestCase):
    def setUp(self):
        from django.utils.text import Truncator
        self.Truncator = Truncator

    def test_chars_truncate(self):
        t = self.Truncator('Hello World')
        result = t.chars(5)
        # The ellipsis character is a combining character, so it doesn't count
        # against the length, resulting in 'Hell…' (4 chars + combining char)
        self.assertEqual(result, 'Hell…')

    def test_chars_no_truncate_needed(self):
        t = self.Truncator('Hi')
        result = t.chars(10)
        self.assertEqual(result, 'Hi')

    def test_chars_with_custom_truncate(self):
        t = self.Truncator('Hello World')
        result = t.chars(5, truncate=' [more]')
        # With custom truncate text, the length calculation accounts for it
        self.assertIn('[more]', result)

    def test_chars_with_placeholder(self):
        t = self.Truncator('Hello World')
        result = t.chars(5, truncate='%(truncated_text)s...')
        # The placeholder format includes the truncated text
        self.assertIn('...', result)

    def test_words_truncate(self):
        t = self.Truncator('Hello World Foo Bar')
        result = t.words(2)
        self.assertEqual(result, 'Hello World…')

    def test_words_no_truncate_needed(self):
        t = self.Truncator('Hi')
        result = t.words(10)
        self.assertEqual(result, 'Hi')

    def test_words_with_custom_truncate(self):
        t = self.Truncator('Hello World Foo Bar')
        result = t.words(2, truncate=' [more]')
        self.assertEqual(result, 'Hello World [more]')

    def test_words_zero_length(self):
        t = self.Truncator('Hello World')
        result = t.words(0)
        # When words=0 with non-html mode, returns ellipsis
        self.assertEqual(result, '…')

    def test_words_html_truncate(self):
        t = self.Truncator('<p>Hello <b>World</b></p>')
        result = t.words(2, html=True)
        self.assertIn('Hello', result)

    def test_words_html_zero_length(self):
        t = self.Truncator('<p>Hello World</p>')
        result = t.words(0, html=True)
        self.assertEqual(result, '')

    def test_html_truncate_no_truncation_needed(self):
        t = self.Truncator('<p>Hello</p>')
        result = t.chars(10, html=True)
        self.assertEqual(result, '<p>Hello</p>')

    def test_html_truncate_regex_no_match(self):
        t = self.Truncator('')
        result = t.chars(5, html=True)
        self.assertEqual(result, '')

    def test_html_truncate(self):
        t = self.Truncator('<p>Hello <b>World</b></p>')
        result = t.chars(6, html=True)
        self.assertIn('Hello', result)

    def test_html_truncate_closes_tags(self):
        t = self.Truncator('<p>Hello World</p>')
        result = t.chars(5, html=True)
        self.assertIn('</p>', result)


