class StreamingBufferTests(SimpleTestCase):
    def setUp(self):
        from django.utils.text import StreamingBuffer
        self.StreamingBuffer = StreamingBuffer

    def test_streaming_buffer_read(self):
        buf = self.StreamingBuffer(b'hello')
        result = buf.read()
        self.assertEqual(result, b'hello')
        self.assertEqual(buf.getvalue(), b'')

    def test_streaming_buffer_multiple_reads(self):
        buf = self.StreamingBuffer(b'hello')
        result1 = buf.read()
        self.assertEqual(result1, b'hello')
        buf.write(b'world')
        result2 = buf.read()
        self.assertEqual(result2, b'world')


