class FormatLazyTests(SimpleTestCase):
    def setUp(self):
        from django.utils.functional import lazy
        from django.utils.text import _format_lazy, format_lazy
        self._format_lazy = _format_lazy
        self.format_lazy = format_lazy

    def test_format_lazy_basic(self):
        result = self._format_lazy('{} {}', 'hello', 'world')
        self.assertEqual(result, 'hello world')

    def test_format_lazy_kwargs(self):
        result = self._format_lazy('{greeting} {name}', greeting='hello', name='world')
        self.assertEqual(result, 'hello world')

    def test_format_lazy_instance(self):
        result = self.format_lazy('{} {}', 'hello', 'world')
        self.assertEqual(str(result), 'hello world')
